INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1000, 13, "2030-04-01 14:00:00", 190801, 1000001, 0, "2020-02-15 15:00:00", "様々なミニゲームをご用意してい\nますよ！\nどのミニゲームで遊びますか？");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1000, 13, "2030-04-01 14:00:00", 190801, 1000002, 0, "2020-02-15 15:00:00", "楽しいミニゲームをご紹介！\nあなたはどのミニゲームで\n遊びますか？");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1001, 13, "2030-04-01 14:00:00", 190801, 1001001, 0, "2020-02-15 15:00:00", "こちらは{0}ルピで\n販売中！\nぜひ購入して\n遊んでくださいね！");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1002, 12, "2030-04-01 14:00:00", 190801, 1002001, 0, "2020-02-15 15:00:00", "動くハートに合わせてタップ！\nシズルさんとエリコさんの\nチョコレートケーキ作りを\nお手伝いしましょう！");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1003, 11, "2030-04-01 14:00:00", 190801, 1003001, 0, "2020-02-15 15:00:00", "クウカさんを引っ張ってより遠く\nへ飛ばしてあげましょう！\n色々なハプニングでクウカさんに\nエクスタシーを届けましょう！");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1004, 3, "2030-04-01 14:00:00", 190801, 1004001, 0, "2020-02-15 15:00:00", "左右をタップしてマジムンを倒し\nましょう！\n放て！\n琉球犬アラウンドシュート！");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1005, 7, "2030-04-01 14:00:00", 190801, 1005001, 0, "2020-02-15 15:00:00", "パネルをタップしてドラゴンズ\nネストのみなさんと一緒に\nしりとり対決をしませんか？\nおしりに「ん」はご法度です。");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1006, 2, "2030-04-01 14:00:00", 190801, 1006001, 0, "2020-05-31 12:00:00", "素早い動きのネズミに合わせ、\nタップで撃退！\nやる気のリンさんと一緒に\n大切なチーズを守りましょう！");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1007, 4, "2030-04-01 14:00:00", 190801, 1007001, 0, "2020-08-15 15:00:00", "ミサトさんや部員のみなさんと\nバッティングの特訓ですよ！\nホームランを目指して、ボールを\nタイミングよく打ち返しましょう");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1008, 6, "2030-04-01 14:00:00", 190801, 1008001, 0, "2021-08-31 12:00:00", "カルミナメダルを使って、\n応援グッズをゲットしましょう！\nメダルはルピを使って\n交換できますよ。\n");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1009, 13, "2030-04-01 14:00:00", 190801, 1009001, 0, "2021-12-18 15:00:00", "食べたプリンはプリンノート\nで確認してみましょう！\nプリンの材料はルピを使って\n購入できますよ。");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1010, 4, "2030-04-01 14:00:00", 190801, 1010001, 0, "2022-02-15 15:00:00", "チームでクイズに挑みましょう！\nソロで自分の実力を試すか、マル\nチで仲間と一緒に遊ぶか、好きな\nモードを選んでくださいね♪");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1011, 6, "2030-04-01 14:00:00", 190801, 1011001, 0, "2022-07-18 15:00:00", "３つのラウンドを駆け抜け、\n総合１位を目指しましょう！\n参加者の皆さんの特徴や、\nＧＰの特徴にも注目です♪");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1012, 6, "2030-04-01 14:00:00", 190801, 1012001, 0, "2023-09-18 15:00:00", "キャルさん、スズナさんと一緒に\nクイズでお勉強しましょう！\n放課後の教室で二人きりって…\nなんだかドキドキしますね♪");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1013, 6, "2030-04-01 14:00:00", 190801, 1013001, 0, "2024-04-18 15:00:00", "魔物の討伐任務にいざ行軍！\nエリコさん、マコトさんの\n頼もしい背中は、\n新兵さんたちの憧れですね♪");
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES (1014, 6, "2030-04-01 14:00:00", 190801, 1014001, 0, "2024-11-18 15:00:00", "バンディ・シスターズのみなさん\nと戦車バトルに挑戦です！\nパーツやメンバーの組み合わせで\nマシンの特徴が変化しますよ♪");
